import { View, Text, StyleSheet } from "react-native";
import { useState, useEffect } from "react";
import AsyncStorage from "@react-native-async-storage/async-storage";
import { registerRootComponent } from "expo";

AsyncStorage.setItem("token", "tok_bat@shop.mn");

const fetchOrders = (token) =>
  new Promise((res, rej) =>
    setTimeout(() => (token ? res([{ id: "o1", total: 129000 }, { id: "o2", total: 59000 }]) : rej(new Error("401"))), 200),
  );

function App() {
  const [orders, setOrders] = useState([]);

  useEffect(() => {
    let alive = true;
    AsyncStorage.getItem("token").then((token) => {
      fetchOrders(token).then((data) => { if (alive) setOrders(data); });
    });
    return () => { alive = false; };
  }, []);

  return (
    <View style={styles.s}>
      <Text style={styles.h}>Миний захиалгууд ({orders.length})</Text>
      {orders.map((o) => (
        <Text key={o.id} testID="order" style={styles.row}>{o.total}₮</Text>
      ))}
    </View>
  );
}

const styles = StyleSheet.create({
  s: { flex: 1, padding: 24, gap: 8 },
  h: { fontSize: 20, fontWeight: "bold" },
  row: { fontSize: 16, paddingVertical: 6 },
});

registerRootComponent(App);
